let currentLocale = (typeof localStorage !== 'undefined' && localStorage.getItem('agrispectra_lang')) || 'en';
const listeners = new Set();


/**
 * Translates crop names dynamically into the active locale.
 * Supports exact crop names, compound names (e.g. "Heirloom Potato", "Drip Tomatoes"),
 * and fallback to English or original name.
 */
export function getCropName(cropName) {
  if (!cropName) return '';
  const str = String(cropName).trim();
  const dict = DICTIONARY[currentLocale] || DICTIONARY.en;

  // 1. Direct key match: 'crop_potato', etc.
  const normalized = str
    .toLowerCase()
    .replace(/\s+crop$/i, '')
    .replace(/^heirloom\s+/i, '')
    .replace(/^drip\s+/i, '')
    .replace(/\s+/g, '_');

  if (dict['crop_' + normalized]) return dict['crop_' + normalized];
  if (DICTIONARY.en['crop_' + normalized] && dict['crop_' + normalized]) return dict['crop_' + normalized];

  // 2. Semantic matching for agricultural crops
  if (/potato/i.test(str)) return t('crop_potato', str);
  if (/tomato/i.test(str)) return t('crop_tomato', str);
  if (/pepper/i.test(str)) return t('crop_bell_pepper', str);
  if (/corn|maize/i.test(str)) return t('crop_sweet_corn', str);
  if (/wheat/i.test(str)) return t('crop_wheat', str);
  if (/cotton/i.test(str)) return t('crop_cotton', str);
  if (/sugarcane/i.test(str)) return t('crop_sugarcane', str);
  if (/paddy|rice/i.test(str)) return t('crop_paddy_rice', str);
  if (/chilli|chili/i.test(str)) return t('crop_chilli', str);
  if (/carrot/i.test(str)) return t('crop_carrots', str);
  if (/strawberr/i.test(str)) return t('crop_strawberries', str);
  if (/almond/i.test(str)) return t('crop_almonds', str);
  if (/citrus|lemon|orange/i.test(str)) return t('crop_citrus', str);
  if (/pistachio/i.test(str)) return t('crop_pistachio', str);
  if (/turmeric/i.test(str)) return t('crop_turmeric', str);
  if (/millet/i.test(str)) return t('crop_millets', str);
  if (/coffee/i.test(str)) return t('crop_coffee', str);
  if (/ginger/i.test(str)) return t('crop_ginger', str);
  if (/onion/i.test(str)) return t('crop_onion', str);
  if (/garlic/i.test(str)) return t('crop_garlic', str);
  if (/leafy|greens|lettuce|spinach/i.test(str)) return t('crop_leafy_greens', str);

  return str;
}

/**
 * Translates agronomic growth stage names dynamically into the active locale.
 */
export function getStageName(stageName) {
  if (!stageName) return '';
  const str = String(stageName).trim();
  if (/vegetative/i.test(str) && /root/i.test(str)) return t('stage_vegetative');
  if (/vegetative/i.test(str)) return t('stage_vegetative_short', t('stage_vegetative'));
  if (/flowering/i.test(str)) return t('stage_flowering');
  if (/tuber/i.test(str)) return t('stage_tuber_bulking');
  if (/ripen/i.test(str)) return t('stage_ripening');
  if (/matur/i.test(str)) return t('stage_maturation');
  if (/sprout/i.test(str) || /emerg/i.test(str)) return t('stage_sprouting');
  if (/harvest/i.test(str)) return t('stage_harvesting');
  if (/crown/i.test(str)) return t('stage_crown_root');
  if (/yield/i.test(str)) return t('stage_yield_formation', str);
  if (/germin/i.test(str)) return t('stage_germination', str);
  if (/head(\s+expansion)?/i.test(str)) return t('stage_head_expansion', str);
  if (/active\s+root/i.test(str)) return t('stage_root_growth', str);

  return str;
}

export function getLocale() {
  return currentLocale;
}

export function setLocale(localeCode) {
  if (DICTIONARY[localeCode]) {
    currentLocale = localeCode;
    try {
      if (typeof localStorage !== 'undefined') {
        localStorage.setItem('agrispectra_lang', localeCode);
      }
    } catch (e) {}
    listeners.forEach(fn => {
      try {
        fn(currentLocale);
      } catch (err) {
        console.warn('[i18n] Listener callback error:', err);
      }
    });
  }
}

export function t(key, fallback = '') {
  const dict = DICTIONARY[currentLocale] || DICTIONARY.en;
  return dict[key] || DICTIONARY.en[key] || fallback || key;
}

export function onLocaleChange(callback) {
  listeners.add(callback);
  return () => listeners.delete(callback);
}
